  A=[ex("Un barco de ejemplo se desplaza v = (4, 3) km (este, norte). Si repite el mismo desplazamiento tres veces, ¿cuál es el desplazamiento total?", "(12, 9)", "Se calcula: 3·(4, 3)."),
     ex("Una persona avanza (6, −2) m. Para volver exactamente al inicio, ¿qué vector debe recorrer?", "(−6, 2)", "Se multiplica por −1."),
     ex("Si w = (9, −6) y v = (3, −2), ¿qué escalar cumple w = k·v?", "3", "9 ÷ 3 y −6 ÷ −2.")],
