# ================================================================ OA 11 clase 3
L(OA11, 3,
  use="Aprenderé a justificar que la homotecia de centro O y razón k es el producto del vector de posición por k, y a calcular la imagen de un punto con cualquier centro. Sirve para usar vectores en transformaciones.",
  prior=["Sé multiplicar un vector por un escalar.", "Sé qué es una homotecia."],
  explain=[
      "Con el centro en el origen O, cada punto P(x, y) tiene vector de posición OP = (x, y). La homotecia de razón k lleva P a P' con OP' = k·OP, es decir P' = (k·x, k·y). Para dos puntos P y Q, el vector P'Q' = k·PQ. Por eso P'Q' es paralelo a PQ y su largo se multiplica por |k|.",
      "Ejemplo: P(1, 2), Q(4, 6) y k = 2. Entonces PQ = (3, 4), P'(2, 4), Q'(8, 12) y P'Q' = (6, 8) = 2·(3, 4). Esto justifica las propiedades que vimos midiendo en la homotecia.",
      "Si el centro es C, no el origen, la fórmula es P' = C + k·(P − C): se resta C para medir desde el centro, se multiplica por k y se suma C para volver. Por ejemplo, con C(1, 1), k = 3 y P(2, 3): P − C = (1, 2), 3·(1, 2) = (3, 6), y P' = (1, 1) + (3, 6) = (4, 7).",
  ],
  vocab=[("vector de posición", "vector desde el origen hasta un punto"), ("centro de homotecia", "punto fijo de la transformación"), ("P − C", "vector desde el centro C hasta P"), ("P'Q'", "vector desde P' hasta Q'"), ("razón k", "escalar que multiplica los vectores desde el centro")],
  worked=[
      ("Centro distinto del origen", "Con centro C(1, 1) y k = 3, halla la imagen de P(2, 3).", ["P − C = (1, 2).", "3·(1, 2) = (3, 6) y P' = (1, 1) + (3, 6)."], "P'(4, 7)"),
      ("Vector entre imágenes", "Con centro en el origen y k = 2, P(1, 2) y Q(4, 6). Calcula PQ y P'Q'.", ["PQ = (3, 4).", "P'(2, 4), Q'(8, 12), entonces P'Q' = (6, 8) = 2·PQ."], "PQ = (3, 4) y P'Q' = (6, 8)"),
  ],
  mist=[
      ("Calcular P' = k·P cuando el centro no es el origen.", "No se midió desde el centro.", "Usa P' = C + k·(P − C)."),
      ("Olvidar sumar C al final.", "El resultado de k·(P − C) es un vector desde el centro.", "Suma C para obtener el punto."),
  ],
  R=[ex("P(2, 3) y Q(7, 5). ¿Cuál es el vector PQ?", "(5, 2)", "(7 − 2, 5 − 3)."),
     ex("Si PQ = (4, −2) y k = 3, ¿cuál es el vector P'Q'?", "(12, −6)", "P'Q' = k·PQ."),
     ex("Con centro en el origen y k = 3, ¿cuál es la imagen de P(2, −1)?", "(6, −3)", "Se multiplican las componentes por 3.")],
  C=[ex("Con centro C(1, 1) y k = 2, ¿cuál es la imagen de P(4, 3)?", "(7, 5)", "(4, 3) − (1, 1) = (3, 2); 2·(3, 2) = (6, 4); más C."),
     ex("Con centro C(2, 0) y k = −1, ¿cuál es la imagen de P(5, 2)?", "(−1, −2)", "P − C = (3, 2); −1·(3, 2) = (−3, −2); más C."),
     ex("Si PQ = (2, −3) y k = −2, ¿cuál es P'Q'?", "(−4, 6)", "−2 por cada componente.")],
  A=[ex("Con centro en el origen y k = 1,5, ¿cuáles son las imágenes de P(4, 6) y Q(10, 2)?", "P'(6, 9) y Q'(15, 3)", "Se multiplican las componentes por 1,5."),
     ex("Con centro C(−1, 2) y k = 2, ¿cuál es la imagen de P(1, 3)?", "(3, 4)", "P − C = (2, 1); 2·(2, 1) = (4, 2); más C."),
     ex("P(2, 3) se transforma en P'(8, 12) con centro en el origen. ¿Cuánto vale k?", "4", "8 ÷ 2 y 12 ÷ 3.")],
  Z=[ex("Ian calculó la imagen de P(3, 3) con centro C(1, 1) y k = 2 como (6, 6). ¿Cuál es la imagen correcta?", "(5, 5)", "P − C = (2, 2); 2·(2, 2) = (4, 4); más C."),
     ex("Con k = 1, ¿qué relación hay entre P' y P?", "P' = P", "La razón 1 no cambia nada.")],
  D=[ex("Con centro C(0, 2) y k = 3, ¿cuál es la imagen de P(1, 3)?", "(3, 5)", "P − C = (1, 1); 3·(1, 1) = (3, 3); más C."),
     ex("Con centro C(1, −1), P(3, 1) se transforma en P'(7, 5). ¿Cuánto vale k?", "3", "P − C = (2, 2) y P' − C = (6, 6).")],
  ctx=[ex("En un juego de ejemplo, una luz en C(2, 2) proyecta el punto P(5, 4) con razón 2. ¿Dónde queda la proyección?", "(8, 6)", "P − C = (3, 2); 2·(3, 2) = (6, 4); más C.")],
  chk=[ex("Con centro en el origen y k = −2, ¿cuál es la imagen de P(3, −1)?", "(−6, 2)", "−2 por cada componente."),
       ex("P(1, 1) y Q(3, 4). ¿Cuál es el vector PQ?", "(2, 3)", "(3 − 1, 4 − 1)."),
       ex("Si PQ = (2, 3) y k = 3, ¿cuál es P'Q'?", "(6, 9)", "3 por cada componente.")],
  op=("Con centro en el origen y k = 3, transforma P(1, 2) y Q(2, 5). Escribe PQ, P'Q' y comprueba que P'Q' = 3·PQ. Luego repite el cálculo con centro C(1, 1) y k = 3. Dibuja ambos resultados en un mismo plano y di en qué se parecen y en qué se distinguen.",
      "Centro origen: P'(3, 6), Q'(6, 15), PQ = (1, 3) y P'Q' = (3, 9). Centro C(1, 1): P − C = (0, 1), entonces P'(1, 4); Q − C = (1, 4), entonces Q'(4, 13); P'Q' = (3, 9). En ambos casos P'Q' = 3·PQ.",
      ["calcula P'Q' en los dos centros", "verifica P'Q' = 3·PQ", "compara resultados"],
      ["cálculos", "dibujo"],
      ["no restar C", "no sumar C al final"],
      "Pide que explique por qué el vector P'Q' no depende del centro."),
  reinforce="Con centro en el origen y k = 2, calcula las imágenes de (1, 1), (3, 0) y (−2, 4).",
  extend="Muestra con P(2, 1), Q(5, 3), C(0, 0) y C(1, 1) que el vector P'Q' es el mismo para k = 2.",
  mat=HOM,
)

